import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { projectsAPI } from '../../services/api';
import AppLayout from '../../components/layout/AppLayout';

const PROJECT_TYPES = [
  { value:'batiment', label:'🏗️ Bâtiment' },
  { value:'route', label:'🛣️ Route' },
  { value:'aep', label:'💧 Adduction d\'eau potable (AEP)' },
  { value:'assainissement', label:'🚰 Assainissement' },
  { value:'pont', label:'🌉 Pont' },
  { value:'autre', label:'📦 Autre' },
];
const STATUS_OPTIONS = [
  { value:'planifie', label:'Planifié' },
  { value:'en_cours', label:'En cours' },
  { value:'suspendu', label:'Suspendu' },
  { value:'termine', label:'Terminé' },
];

export default function CreateProjectPage() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ name:'', description:'', project_type:'batiment', location:'', status:'planifie', start_date:'', end_date:'', budget:'' });
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    setForm(p => ({ ...p, [e.target.name]: e.target.value }));
    if (errors[e.target.name]) setErrors(p => ({ ...p, [e.target.name]: '' }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    const payload = { ...form };
    if (!payload.start_date) delete payload.start_date;
    if (!payload.end_date) delete payload.end_date;
    if (!payload.budget) delete payload.budget;
    try {
      const res = await projectsAPI.create(payload);
      toast.success('Projet créé avec succès !');
      navigate(`/projects/${res.data.id}`);
    } catch (err) {
      const data = err.response?.data;
      if (data && typeof data === 'object') setErrors(data);
      else toast.error('Erreur lors de la création');
    } finally { setLoading(false); }
  };

  return (
    <AppLayout>
      <div style={{ padding:'32px 40px', maxWidth:700 }} className="animate-fade-in">
        <div style={{ marginBottom:32 }}>
          <button onClick={() => navigate('/projects')} style={{ background:'none', border:'none', color:'#6B7280', cursor:'pointer', fontSize:14, marginBottom:12, fontFamily:'Barlow', display:'flex', alignItems:'center', gap:6 }}>
            ← Retour aux projets
          </button>
          <h1 style={{ fontFamily:'Bebas Neue', fontSize:42, color:'#fff', letterSpacing:1, margin:0 }}>
            Nouveau <span style={{ color:'#F59E0B' }}>Projet</span>
          </h1>
          <p style={{ color:'#6B7280', margin:'4px 0 0' }}>Remplissez les informations de votre projet</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="card" style={{ display:'flex', flexDirection:'column', gap:24 }}>
            <div className="input-group">
              <label className="input-label">Nom du projet *</label>
              <input name="name" className={`input-field ${errors.name ? 'error':''}`}
                placeholder="Ex: Construction école Bamako Coura" value={form.name} onChange={handleChange} required />
              {errors.name && <span className="input-error">{errors.name}</span>}
            </div>

            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20 }}>
              <div className="input-group">
                <label className="input-label">Type de travaux *</label>
                <select name="project_type" className="input-field" value={form.project_type} onChange={handleChange}>
                  {PROJECT_TYPES.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
                </select>
              </div>
              <div className="input-group">
                <label className="input-label">Statut</label>
                <select name="status" className="input-field" value={form.status} onChange={handleChange}>
                  {STATUS_OPTIONS.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
                </select>
              </div>
            </div>

            <div className="input-group">
              <label className="input-label">Localisation</label>
              <input name="location" className="input-field"
                placeholder="Ex: Bamako, Commune IV, Mali" value={form.location} onChange={handleChange} />
            </div>

            <div className="input-group">
              <label className="input-label">Description</label>
              <textarea name="description" className="input-field"
                placeholder="Description du projet..." value={form.description} onChange={handleChange}
                rows={4} style={{ resize:'vertical' }} />
            </div>

            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20 }}>
              <div className="input-group">
                <label className="input-label">Date de début</label>
                <input name="start_date" type="date" className="input-field" value={form.start_date} onChange={handleChange} />
              </div>
              <div className="input-group">
                <label className="input-label">Date de fin</label>
                <input name="end_date" type="date" className="input-field" value={form.end_date} onChange={handleChange} />
              </div>
            </div>

            <div className="input-group">
              <label className="input-label">Budget (FCFA)</label>
              <input name="budget" type="number" className="input-field"
                placeholder="Ex: 50000000" value={form.budget} onChange={handleChange} min="0" />
            </div>

            <div style={{ display:'flex', gap:12, paddingTop:8 }}>
              <button type="submit" className="btn btn-primary btn-lg" disabled={loading} style={{ flex:1 }}>
                {loading ? 'Création...' : '✓ Créer le projet'}
              </button>
              <button type="button" className="btn btn-ghost btn-lg" onClick={() => navigate('/projects')}>
                Annuler
              </button>
            </div>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}
